CREATE TABLE IF NOT EXISTS usuarios (id BIGINT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(120) NOT NULL, correo VARCHAR(190) NOT NULL UNIQUE, clave_hash VARCHAR(100) NOT NULL, rol VARCHAR(15) NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS productos (id BIGINT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(120) NOT NULL, categoria VARCHAR(30) NOT NULL, descripcion VARCHAR(500) NOT NULL, precio DECIMAL(12,2) NOT NULL, imagen VARCHAR(100) NOT NULL, activo BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS pedidos (id BIGINT AUTO_INCREMENT PRIMARY KEY, usuario_id BIGINT NOT NULL, codigo VARCHAR(30) UNIQUE, estado VARCHAR(30) NOT NULL, total DECIMAL(12,2) NOT NULL, creado_en TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(usuario_id) REFERENCES usuarios(id));
CREATE TABLE IF NOT EXISTS pedido_detalles (id BIGINT AUTO_INCREMENT PRIMARY KEY, pedido_id BIGINT NOT NULL, producto_id BIGINT NOT NULL, cantidad INT NOT NULL, precio_unitario DECIMAL(12,2) NOT NULL, FOREIGN KEY(pedido_id) REFERENCES pedidos(id), FOREIGN KEY(producto_id) REFERENCES productos(id));
CREATE TABLE IF NOT EXISTS historial_estados (id BIGINT AUTO_INCREMENT PRIMARY KEY, pedido_id BIGINT NOT NULL, estado VARCHAR(30) NOT NULL, responsable_id BIGINT NOT NULL, fecha TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(pedido_id) REFERENCES pedidos(id), FOREIGN KEY(responsable_id) REFERENCES usuarios(id));
